CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE workspaces(id uuid PRIMARY KEY, name text NOT NULL);
INSERT INTO workspaces VALUES ('00000000-0000-0000-0000-000000000001','Internal') ON CONFLICT DO NOTHING;
CREATE TABLE users(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE invitations(token_hash text PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), expires_at timestamptz NOT NULL);
CREATE TABLE api_keys(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, name text NOT NULL, token_hash text NOT NULL UNIQUE, prefix text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE connections(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, provider text NOT NULL CHECK(provider IN ('whatsapp_web','whatsapp_cloud','instagram','telegram')), label text NOT NULL, identity text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'disconnected', detail text NOT NULL DEFAULT '', credentials bytea, session_data bytea, external_id text, checkpoint bytea, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX connection_external ON connections(provider,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE conversations(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, connection_id uuid NOT NULL REFERENCES connections ON DELETE CASCADE, external_id text NOT NULL, title text NOT NULL, is_group boolean NOT NULL DEFAULT false, last_message_at timestamptz NOT NULL DEFAULT now(), last_inbound_at timestamptz, read_at timestamptz, UNIQUE(connection_id,external_id));
CREATE TABLE media(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, connection_id uuid REFERENCES connections ON DELETE CASCADE, name text NOT NULL, mime text NOT NULL, size bigint NOT NULL, path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, conversation_id uuid NOT NULL REFERENCES conversations ON DELETE CASCADE, connection_id uuid NOT NULL REFERENCES connections ON DELETE CASCADE, external_id text, direction text NOT NULL CHECK(direction IN ('in','out')), sender text NOT NULL DEFAULT '', kind text NOT NULL DEFAULT 'text', text text NOT NULL DEFAULT '', media_id uuid REFERENCES media ON DELETE SET NULL, status text NOT NULL DEFAULT 'received', reply_to text NOT NULL DEFAULT '', metadata jsonb NOT NULL DEFAULT '{}', edited_at timestamptz, deleted_at timestamptz, sent_at timestamptz NOT NULL DEFAULT now(), UNIQUE(connection_id,external_id));
CREATE INDEX messages_page ON messages(conversation_id,sent_at DESC,id DESC);
CREATE INDEX conversations_page ON conversations(workspace_id,last_message_at DESC);
CREATE TABLE jobs(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, kind text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, run_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_pending ON jobs(state,run_at);
CREATE TABLE events(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, type text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_subscriptions(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, url text NOT NULL, secret bytea NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, subscription_id uuid NOT NULL REFERENCES webhook_subscriptions ON DELETE CASCADE, event_id uuid NOT NULL REFERENCES events ON DELETE CASCADE, attempts integer NOT NULL DEFAULT 0, state text NOT NULL DEFAULT 'pending', response_code integer, error text NOT NULL DEFAULT '', UNIQUE(subscription_id,event_id));
CREATE TABLE oauth_states(token_hash text PRIMARY KEY, connection_id uuid NOT NULL REFERENCES connections ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE audit(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, actor text NOT NULL, action text NOT NULL, resource_id text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
